/// Cryptography for PeerDesk mobile, wire-compatible with peerdesk/crypto.py.
///
/// Mirrors the Python host exactly:
///   * ephemeral X25519 key agreement
///   * HKDF-SHA256(info="peerdesk-session-v1") -> 32-byte session key
///   * Fernet (AES-128-CBC + HMAC-SHA256) record protection
///   * PBKDF2-HMAC-SHA256 (200k) + HMAC challenge-response for passwords
///
/// Interop with the Python implementation is verified by
/// test/crypto_interop_test.dart against vectors generated by the real
/// `cryptography` package.
library;

import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:cryptography/cryptography.dart';

const int kKeyLen = 32;
const int kPbkdf2Iterations = 200000;
const String kSessionInfo = 'peerdesk-session-v1';

final _x25519 = X25519();
final _hmacSha256 = Hmac.sha256();
final _aesCbc = AesCbc.with128bits(macAlgorithm: MacAlgorithm.empty);
final _rng = Random.secure();

Uint8List randomBytes(int n) {
  final b = Uint8List(n);
  for (var i = 0; i < n; i++) {
    b[i] = _rng.nextInt(256);
  }
  return b;
}

String b64e(List<int> data) => base64.encode(data);
Uint8List b64d(String text) => base64.decode(text);

/// A newly generated X25519 keypair plus the raw 32-byte public key to send.
class KeyExchange {
  final SimpleKeyPair keyPair;
  final Uint8List publicBytes;
  KeyExchange(this.keyPair, this.publicBytes);
}

Future<KeyExchange> generateKeyExchange() async {
  final kp = await _x25519.newKeyPair();
  final pub = await kp.extractPublicKey();
  return KeyExchange(kp, Uint8List.fromList(pub.bytes));
}

/// Derive the 32-byte session key from our keypair and the peer's public key,
/// matching derive_shared_key() in crypto.py (HKDF-SHA256, empty salt == None).
Future<Uint8List> deriveSharedKey(
    SimpleKeyPair keyPair, List<int> peerPublicBytes,
    {String info = kSessionInfo}) async {
  final remote =
      SimplePublicKey(List<int>.from(peerPublicBytes), type: KeyPairType.x25519);
  final shared = await _x25519.sharedSecretKey(
      keyPair: keyPair, remotePublicKey: remote);
  final sharedBytes = await shared.extractBytes();
  final hkdf = Hkdf(hmac: _hmacSha256, outputLength: kKeyLen);
  final out = await hkdf.deriveKey(
    secretKey: SecretKey(sharedBytes),
    nonce: const <int>[], // empty salt == Python salt=None (HMAC zero-pads)
    info: utf8.encode(info),
  );
  return Uint8List.fromList(await out.extractBytes());
}

/// PBKDF2-HMAC-SHA256, matching derive_key() in crypto.py.
Future<Uint8List> deriveKeyPbkdf2(String password, List<int> salt,
    {int iterations = kPbkdf2Iterations}) async {
  final pbkdf2 = Pbkdf2(
    macAlgorithm: _hmacSha256,
    iterations: iterations,
    bits: kKeyLen * 8,
  );
  final out = await pbkdf2.deriveKey(
    secretKey: SecretKey(utf8.encode(password)),
    nonce: List<int>.from(salt),
  );
  return Uint8List.fromList(await out.extractBytes());
}

/// HMAC-SHA256(key, nonce) -- the proof a viewer returns for a login challenge.
Future<Uint8List> challengeAnswer(List<int> key, List<int> nonce) async {
  final mac = await _hmacSha256.calculateMac(
    List<int>.from(nonce),
    secretKey: SecretKey(List<int>.from(key)),
  );
  return Uint8List.fromList(mac.bytes);
}

bool constantTimeEquals(List<int> a, List<int> b) {
  if (a.length != b.length) return false;
  var diff = 0;
  for (var i = 0; i < a.length; i++) {
    diff |= a[i] ^ b[i];
  }
  return diff == 0;
}

/// Authenticated encryption compatible with Python's Fernet (as used by
/// crypto.SecureChannel). Tokens are byte-for-byte interchangeable.
class SecureChannel {
  final Uint8List _signingKey; // first 16 bytes of the session key
  final Uint8List _encKey; // last 16 bytes of the session key

  SecureChannel(List<int> key)
      : assert(key.length == kKeyLen, 'key must be 32 bytes'),
        _signingKey = Uint8List.fromList(key.sublist(0, 16)),
        _encKey = Uint8List.fromList(key.sublist(16, 32));

  /// Produce a urlsafe-base64 Fernet token (returned as ASCII bytes, exactly
  /// what Python's fernet.encrypt() yields and what the Link puts on the wire).
  Future<Uint8List> encrypt(List<int> data) async {
    final iv = randomBytes(16);
    final secretBox = await _aesCbc.encrypt(
      List<int>.from(data),
      secretKey: SecretKey(_encKey),
      nonce: iv,
    );
    final ts = ByteData(8)
      ..setUint64(0, DateTime.now().millisecondsSinceEpoch ~/ 1000, Endian.big);
    final body = BytesBuilder()
      ..addByte(0x80)
      ..add(ts.buffer.asUint8List())
      ..add(iv)
      ..add(secretBox.cipherText);
    final bodyBytes = body.toBytes();
    final mac = await _hmacSha256.calculateMac(bodyBytes,
        secretKey: SecretKey(_signingKey));
    final token = BytesBuilder()
      ..add(bodyBytes)
      ..add(mac.bytes);
    return Uint8List.fromList(utf8.encode(base64Url.encode(token.toBytes())));
  }

  /// Open a Fernet token (ASCII base64 bytes). Throws on tampering.
  Future<Uint8List> decrypt(List<int> tokenAsciiBytes) async {
    final token = base64Url.decode(_normalisePadding(utf8.decode(tokenAsciiBytes)));
    if (token.isEmpty || token[0] != 0x80) {
      throw StateError('bad Fernet version');
    }
    if (token.length < 1 + 8 + 16 + 32) {
      throw StateError('Fernet token too short');
    }
    final mac = token.sublist(token.length - 32);
    final body = token.sublist(0, token.length - 32);
    final expected = await _hmacSha256.calculateMac(body,
        secretKey: SecretKey(_signingKey));
    if (!constantTimeEquals(expected.bytes, mac)) {
      throw StateError('ciphertext failed authentication');
    }
    final iv = body.sublist(9, 25);
    final ct = body.sublist(25);
    final clear = await _aesCbc.decrypt(
      SecretBox(ct, nonce: iv, mac: Mac.empty),
      secretKey: SecretKey(_encKey),
    );
    return Uint8List.fromList(clear);
  }

  static String _normalisePadding(String s) {
    final mod = s.length % 4;
    if (mod == 0) return s;
    return s + '=' * (4 - mod);
  }
}
